    public sealed class SpeechService {
        const string EngineUrl="https://github.com/ggml-org/whisper.cpp/releases/download/b5454/whisper-bin-x64.zip",EngineHash="6ba69e3482d7826214f90a6a9c84ca07782aec1e1d0c6a7c30c994fd5d816ccb";
        const string BaseHash="60ed5bc3dd14eea856493d334349b405782ddcaf0028d4b5df4088345fba2efe",TinyHash="be07e048e1e599ad46341c8d2a135645097a538221678b7acdd1b1919c6e1b21";
        readonly string directory,configPath,components;readonly object gate=new object();readonly Func<HttpMessageHandler> handlerFactory;SpeechConfig config;
        public SpeechService(string dataDir,Func<HttpMessageHandler> factory=null){directory=dataDir;configPath=Path.Combine(dataDir,"speech-settings.json");components=Path.Combine(dataDir,"speech-components");handlerFactory=factory;try{config=Library.Json.Deserialize<SpeechConfig>(File.ReadAllText(configPath,Encoding.UTF8));}catch{}if(config==null)config=new SpeechConfig();}
        static string Value(Dictionary<string,object> values,string key,string fallback){return values.ContainsKey(key)?Convert.ToString(values[key]):fallback;}
        SpeechConfig Snapshot(){lock(gate)return Library.Json.Deserialize<SpeechConfig>(Library.Json.Serialize(config));}
        static void Atomic(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,value,new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
        public static Uri Endpoint(string value){Uri uri;if(!Uri.TryCreate((value??"").Trim(),UriKind.Absolute,out uri)||!String.IsNullOrEmpty(uri.UserInfo)||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment)||!(uri.Scheme=="https"||uri.Scheme=="http"&&uri.IsLoopback))throw new InvalidDataException("请输入 HTTPS 语音接口地址，本机服务可使用 HTTP。");string path=uri.AbsoluteUri.TrimEnd('/');if(!path.EndsWith("/audio/transcriptions",StringComparison.OrdinalIgnoreCase))path+="/audio/transcriptions";return new Uri(path);}
        public object Public(){var c=Snapshot();return new{mode=c.mode,endpoint=c.endpoint,model=c.model,responseFormat=c.responseFormat,language=c.language,hasKey=!String.IsNullOrEmpty(c.protectedKey),localReady=File.Exists(c.executable)&&File.Exists(c.modelFile),engineName=Path.GetFileName(c.executable),modelName=Path.GetFileName(c.modelFile)};}
        public object Save(Dictionary<string,object> values){lock(gate){var next=Snapshot();next.mode=Value(values,"mode",next.mode);next.endpoint=Value(values,"endpoint",next.endpoint).Trim();next.model=Value(values,"model",next.model).Trim();next.responseFormat=Value(values,"responseFormat",next.responseFormat);next.language=Value(values,"language",next.language);
            if(!new[]{"local","api"}.Contains(next.mode)||!new[]{"verbose_json","srt"}.Contains(next.responseFormat)||next.model.Length<1||next.model.Length>200||!Regex.IsMatch(next.language??"","^(auto|[a-z]{2,3})$"))throw new InvalidDataException("语音识别配置无效。");Uri endpoint=Endpoint(next.endpoint);string key=Value(values,"apiKey","").Trim();bool clear=values.ContainsKey("clearKey")&&Convert.ToBoolean(values["clearKey"]);
            if(clear)next.protectedKey="";if(key.Length>0){if(key.Length>4096||key.Any(Char.IsControl))throw new InvalidDataException("API 密钥格式无效。");next.protectedKey=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(key),null,DataProtectionScope.CurrentUser));}else if(!clear&&!String.IsNullOrEmpty(config.protectedKey)&&endpoint!=Endpoint(config.endpoint))throw new InvalidDataException("更换接口地址时，请重新填写对应服务的密钥。");Atomic(configPath,Library.Json.Serialize(next));config=next;return Public();}}
        public object ChooseLocal(string path,bool model){lock(gate){if(!File.Exists(path)||model&&!new[]{".bin",".gguf"}.Contains(Path.GetExtension(path).ToLowerInvariant())||!model&&Path.GetFileName(path)!="whisper-cli.exe")throw new InvalidDataException("请选择有效的 Whisper 程序或模型。");if(model)config.modelFile=Path.GetFullPath(path);else config.executable=Path.GetFullPath(path);Atomic(configPath,Library.Json.Serialize(config));return Public();}}
        static async Task Download(string url,string file,string hash,long limit,CancellationToken token,Action<long,long> progress){
            using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(token))using(var client=new HttpClient()){deadline.CancelAfter(TimeSpan.FromMinutes(20));client.Timeout=TimeSpan.FromMinutes(20);using(var reply=await client.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,deadline.Token)){reply.EnsureSuccessStatusCode();long total=reply.Content.Headers.ContentLength??limit;if(total>limit)throw new InvalidDataException("语音组件下载大小异常。");using(var input=await reply.Content.ReadAsStreamAsync())using(var output=File.Create(file)){var buffer=new byte[65536];int read;long received=0,last=0;while((read=await input.ReadAsync(buffer,0,buffer.Length,deadline.Token))>0){received+=read;if(received>limit)throw new InvalidDataException("语音组件下载大小异常。");await output.WriteAsync(buffer,0,read,deadline.Token);if(received-last>512*1024){last=received;progress(received,total);}}}}}
            token.ThrowIfCancellationRequested();if(await Task.Run(()=>DownloadTools.HashFile(file),token)!=hash)throw new InvalidDataException("语音组件校验失败，请重新下载。");
        }
        public async Task<object> Install(string size,CancellationToken token,Action<SpeechProgress> progress){
            if(!new[]{"tiny","base"}.Contains(size))throw new InvalidDataException("请选择有效的 Whisper 程序或模型。");Directory.CreateDirectory(components);string archive=Path.Combine(components,"engine-"+Guid.NewGuid().ToString("N")+".zip"),modelTemp=Path.Combine(components,"model-"+Guid.NewGuid().ToString("N")+".download"),model=Path.Combine(components,"ggml-"+size+".bin"),engine=Path.Combine(components,"b5454");
            try{
                if(!File.Exists(Path.Combine(engine,"whisper-cli.exe"))){progress(new SpeechProgress{stage="engine",percent=0});await Download(EngineUrl,archive,EngineHash,16*1024*1024,token,(a,b)=>progress(new SpeechProgress{stage="engine",percent=100.0*a/b}));using(var zip=ZipFile.OpenRead(archive)){Directory.CreateDirectory(engine);foreach(var entry in zip.Entries.Where(e=>e.Name=="whisper-cli.exe"||e.Name.EndsWith(".dll",StringComparison.OrdinalIgnoreCase))){if(entry.Length>100*1024*1024||Path.GetFileName(entry.Name)!=entry.Name)throw new InvalidDataException("语音组件校验失败，请重新下载。");using(var input=entry.Open())using(var output=File.Create(Path.Combine(engine,entry.Name)))input.CopyTo(output);}}}
                string hash=size=="tiny"?TinyHash:BaseHash;if(!File.Exists(model)||await Task.Run(()=>DownloadTools.HashFile(model))!=hash){progress(new SpeechProgress{stage="model",percent=0});await Download("https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-"+size+".bin",modelTemp,hash,160*1024*1024,token,(a,b)=>progress(new SpeechProgress{stage="model",percent=100.0*a/b}));if(File.Exists(model))File.Replace(modelTemp,model,null);else File.Move(modelTemp,model);}
                token.ThrowIfCancellationRequested();lock(gate){config.executable=Path.Combine(engine,"whisper-cli.exe");config.modelFile=model;Atomic(configPath,Library.Json.Serialize(config));}return Public();
            }finally{if(File.Exists(archive))File.Delete(archive);if(File.Exists(modelTemp))File.Delete(modelTemp);}
        }
        public static List<Cue> ParseResponse(string text,string format,double offset,double duration){
            if(format=="srt"){var rows=Subtitles.ParseText(text,".srt").cues;return Validate(rows,offset,duration);}
            try{var root=Library.Json.DeserializeObject(text) as Dictionary<string,object>;var segments=root!=null&&root.ContainsKey("segments")?root["segments"] as object[]:null;if(segments==null)throw new FormatException();var rows=new List<Cue>();foreach(var entry in segments){var row=entry as Dictionary<string,object>;if(row==null)throw new FormatException();rows.Add(new Cue{start=Convert.ToDouble(row["start"],CultureInfo.InvariantCulture),end=Convert.ToDouble(row["end"],CultureInfo.InvariantCulture),text=Convert.ToString(row["text"])});}return Validate(rows,offset,duration);}catch(InvalidDataException){throw;}catch{throw new InvalidDataException("语音服务未返回有效时间戳，请选择支持字幕时间戳的模型。");}
        }
        static List<Cue> Validate(List<Cue> rows,double offset,double duration){if(rows.Count>50000||rows.Any(c=>Double.IsNaN(c.start)||Double.IsInfinity(c.start)||Double.IsNaN(c.end)||Double.IsInfinity(c.end)||c.start<0||c.end<c.start||c.start>duration+2||(c.text??"").Length>20000))throw new InvalidDataException("语音服务返回的字幕时间戳无效。");return rows.Where(c=>!String.IsNullOrWhiteSpace(c.text)&&c.end>c.start&&c.start<duration).Select(c=>new Cue{start=offset+c.start,end=offset+Math.Min(duration,c.end),text=c.text.Trim()}).OrderBy(c=>c.start).ToList();}
        async Task<List<Cue>> Cloud(string audio,SpeechConfig c,double offset,double duration,CancellationToken token){
            Uri endpoint=Endpoint(c.endpoint);string key="";if(!String.IsNullOrEmpty(c.protectedKey))try{key=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(c.protectedKey),null,DataProtectionScope.CurrentUser));}catch{throw new InvalidDataException("语音密钥无法解密，请重新填写。");}
            using(var handler=handlerFactory!=null?handlerFactory():new HttpClientHandler{AllowAutoRedirect=false,UseProxy=!endpoint.IsLoopback})using(var client=new HttpClient(handler))using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(token))using(var request=new HttpRequestMessage(HttpMethod.Post,endpoint)){
                client.Timeout=TimeSpan.FromMinutes(5);deadline.CancelAfter(TimeSpan.FromMinutes(5));if(key!="")request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",key);var form=new MultipartFormDataContent();request.Content=form;form.Add(new StringContent(c.model),"model");form.Add(new StringContent(c.responseFormat),"response_format");if(c.language!="auto")form.Add(new StringContent(c.language),"language");if(c.responseFormat=="verbose_json")form.Add(new StringContent("segment"),"timestamp_granularities[]");var content=new StreamContent(File.OpenRead(audio));content.Headers.ContentType=new MediaTypeHeaderValue("audio/wav");form.Add(content,"file","audio.wav");
                try{using(var reply=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,deadline.Token)){if(!reply.IsSuccessStatusCode){int status=(int)reply.StatusCode;if(status==401||status==403)throw new InvalidDataException("语音服务认证失败，请检查独立的语音 API 密钥。");if(status==429)throw new InvalidDataException("语音服务额度不足或请求过于频繁。");throw new InvalidDataException("语音服务请求失败，请检查地址、模型和响应格式。");}using(var input=await reply.Content.ReadAsStreamAsync())using(var output=new MemoryStream()){var buffer=new byte[8192];int read;while((read=await input.ReadAsync(buffer,0,buffer.Length,deadline.Token))>0){if(output.Length+read>8*1024*1024)throw new InvalidDataException("语音服务返回的字幕过大。");output.Write(buffer,0,read);}return ParseResponse(Encoding.UTF8.GetString(output.ToArray()),c.responseFormat,offset,duration);}}}
                catch(OperationCanceledException){if(token.IsCancellationRequested)throw;throw new InvalidDataException("语音识别超时，请重试或使用更短的片段。");}catch(HttpRequestException){throw new InvalidDataException("无法连接语音服务，请检查网络和接口地址。");}
            }
        }
        public async Task<SubtitleTrack> Generate(string source,string encoder,string probe,CancellationToken token,Action<SpeechProgress> progress){
            var c=Snapshot();if(c.mode=="local"&&(!File.Exists(c.executable)||!File.Exists(c.modelFile)))throw new InvalidDataException("请先安装或选择本地 Whisper 程序和模型。");var details=await MediaSequence.Probe(probe,source,token);double duration;if(!Double.TryParse(details.format.duration,NumberStyles.Float,CultureInfo.InvariantCulture,out duration)||duration<=0||duration>12*3600||!details.streams.Any(s=>s.codec_type=="audio"))throw new InvalidDataException("未找到可识别的音轨，或媒体超过 12 小时。");
            string work=Path.Combine(directory,"speech-work",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);var files=new List<string>();var result=new SubtitleTrack{name=c.mode=="local"?"Whisper · AI":"ASR · AI",generated=true};int count=(int)Math.Ceiling(duration/480);
            try{for(int index=0;index<count;index++){
                    token.ThrowIfCancellationRequested();double offset=index*480,length=Math.Min(480,duration-offset);string audio=Path.Combine(work,"audio.wav"),prefix=Path.Combine(work,"captions"),srt=prefix+".srt";files.Add(audio);files.Add(srt);progress(new SpeechProgress{stage="extract",completed=index,total=count,percent=100.0*index/count});
                    int code=await DownloadTools.Run(encoder,new[]{"-hide_banner","-nostdin","-v","error","-protocol_whitelist","file,pipe","-ss",offset.ToString(CultureInfo.InvariantCulture),"-t",length.ToString(CultureInfo.InvariantCulture),"-i",source,"-map","0:a:0","-vn","-ar","16000","-ac","1","-c:a","pcm_s16le","-y",audio},line=>{},line=>{},token,work);if(code!=0||!File.Exists(audio)||new FileInfo(audio).Length<44||new FileInfo(audio).Length>20*1024*1024)throw new InvalidDataException("无法提取音轨，请检查本地媒体组件和文件格式。");
                    progress(new SpeechProgress{stage="recognize",completed=index,total=count,percent=100.0*index/count});List<Cue> cues;
                    if(c.mode=="api")cues=await Cloud(audio,c,offset,length,token);
                    else{if(File.Exists(srt))File.Delete(srt);code=await DownloadTools.Run(c.executable,new[]{"-m",c.modelFile,"-f",audio,"-l",c.language,"-osrt","-of",prefix,"-pp","-ng","-t",Math.Max(1,Math.Min(8,Environment.ProcessorCount-1)).ToString(CultureInfo.InvariantCulture)},line=>{},line=>{var match=Regex.Match(line,@"progress\s*=\s*(\d+)%");int percent;if(match.Success&&Int32.TryParse(match.Groups[1].Value,out percent))progress(new SpeechProgress{stage="recognize",completed=index,total=count,percent=100.0*(index+Math.Min(100,percent)/100.0)/count});},token,work);if(code!=0||!File.Exists(srt))throw new InvalidDataException("本地识别失败，请检查 Whisper 组件、模型和电脑兼容性。");if(new FileInfo(srt).Length>8*1024*1024)throw new InvalidDataException("语音服务返回的字幕过大。");cues=Validate(Subtitles.Read(srt).cues,offset,length);}
                    result.cues.AddRange(cues);if(result.cues.Count>50000||result.cues.Sum(cue=>(long)cue.text.Length)>2000000)throw new InvalidDataException("语音服务返回的字幕过大。");File.Delete(audio);if(File.Exists(srt))File.Delete(srt);progress(new SpeechProgress{stage="recognize",completed=index+1,total=count,percent=100.0*(index+1)/count});
                }token.ThrowIfCancellationRequested();if(result.cues.Count==0)throw new InvalidDataException("未识别到可用语音，请检查音轨或更换模型。");return result;
            }finally{foreach(string file in files.Distinct())if(File.Exists(file))File.Delete(file);if(Directory.Exists(work)&&!Directory.EnumerateFileSystemEntries(work).Any())Directory.Delete(work);}
        }
    }
    public partial class MainWindow {
        static readonly string[] SpeechActions={"speechConfig","saveSpeechConfig","chooseSpeechFile","installSpeech","generateSubtitles","cancelSpeech"};
        readonly Dictionary<string,CancellationTokenSource> speechJobs=new Dictionary<string,CancellationTokenSource>();SpeechService speech;
        readonly Dictionary<string,Form> speechOwners=new Dictionary<string,Form>();
        SpeechService Speech {get{return speech??(speech=new SpeechService(normalLibrary.DataDir));}}
        void CancelSpeechJobs(){foreach(var job in speechJobs.Values.ToArray())job.Cancel();}
        void CancelSpeechOwner(Form owner){foreach(var pair in speechOwners.Where(p=>p.Value==owner).ToArray()){CancellationTokenSource cancel;if(speechJobs.TryGetValue(pair.Key,out cancel))cancel.Cancel();}}
        async Task<object> HandleSpeechAction(string action,Dictionary<string,object> args,Form owner){
            if(action=="cancelSpeech"){CancellationTokenSource active;if(speechJobs.TryGetValue(StringArg(args,"jobId"),out active))active.Cancel();return true;}
            library.RequireAiMode();if(action=="speechConfig")return Speech.Public();if(speechJobs.Count>0)throw new InvalidOperationException("请先停止当前字幕任务。");if(action=="saveSpeechConfig")return Speech.Save(args);
            if(action=="chooseSpeechFile"){bool model=StringArg(args,"kind")=="model";nativeFileDialogOpen=true;try{using(var dialog=new OpenFileDialog{Title=L(model?"选择 Whisper 模型":"选择 Whisper 程序"),Filter=model?"Whisper|*.bin;*.gguf":"Whisper|whisper-cli.exe",Multiselect=false}){if(dialog.ShowDialog(owner)!=DialogResult.OK)return Speech.Public();return Speech.ChooseLocal(dialog.FileName,model);}}finally{nativeFileDialogOpen=false;}}
            string jobId=StringArg(args,"jobId");if(!Regex.IsMatch(jobId,"^[A-Za-z0-9-]{1,80}$"))throw new InvalidDataException("语音识别配置无效。");var target=library;
            using(var cancel=ModuleCancellation()){speechJobs.Add(jobId,cancel);speechOwners.Add(jobId,owner);backgroundLibraryWrites++;try{
                    Action<SpeechProgress> progress=p=>{if(!IsDisposed)BeginInvoke((Action)(()=>{if(!IsDisposed)Notify("speechProgress",new{jobId=jobId,stage=p.stage,completed=p.completed,total=p.total,percent=p.percent});}));};
                    if(action=="installSpeech")return await Speech.Install(StringArg(args,"size"),cancel.Token,progress);
                    var entry=RequireEntry(args);if(entry.kind!="video")throw new InvalidDataException("请先打开视频。");string encoder=downloads.LocalEncoder,probe=downloads.LocalProbe;if(encoder==null||probe==null)throw new InvalidDataException("请先配置本地媒体组件。");var track=await Speech.Generate(entry.path,encoder,probe,cancel.Token,progress);cancel.Token.ThrowIfCancellationRequested();if(library!=target)throw new OperationCanceledException();entry.generatedSubtitles=track;target.Save();Notify("libraryChanged",null);return track;
                }catch(OperationCanceledException){return new{cancelled=true};}finally{speechJobs.Remove(jobId);speechOwners.Remove(jobId);backgroundLibraryWrites--;}}
        }
    }
